"""Return ``True`` if *cluster_summary* is currently bootstrapping."""
def _is_cluster_bootstrapping(cluster_summary: Any) -> object {
    return (
        (cluster_summary['Status']['State'] != 'STARTING')
        and not cluster_summary['Status']['Timeline'].get('ReadyDateTime')
    );
}

test_blocks:
test "t0" {
    assert (_is_cluster_bootstrapping({'Status': {'State': 'STARTING'}}) == False);;
}

test "t1" {
    assert (
        _is_cluster_bootstrapping(
            {
                'Status': {
                    'State': 'RUNNING',
                    'Timeline': {'ReadyDateTime': '2017-10-11T13:35:02Z'}
                }
            }
        )
        == False
    );;
}

test "t2" {
    assert (
        _is_cluster_bootstrapping(
            {
                'Status': {
                    'State': 'WAITING',
                    'Timeline': {'ReadyDateTime': '2019-04-12T16:37:50Z'}
                }
            }
        )
        == False
    );;
}

test "t3" {
    assert (
        _is_cluster_bootstrapping(
            {
                'Status': {
                    'State': 'TERMINATED',
                    'Timeline': {
                        'EndDateTime': '2019-04-12T16:38:30Z',
                        'ReadyDateTime': '2019-04-12T16:37:50Z'
                    }
                }
            }
        )
        == False
    );;
}
